mapper.select:
SELECT p.id AS payableId, p.payable_no AS payableNo, p.purchase_order_id AS purchaseOrderId, p.supplier_id AS supplierId, p.supplier_name_snapshot AS supplierNameSnapshot, p.entry_type AS entryType, p.amount, po.purchaser_id AS purchaserId FROM finance_payable p LEFT JOIN purchase_receipt pr ON pr.id = p.source_id AND pr.deleted = FALSE LEFT JOIN purchase_order po ON po.id = pr.purchase_order_id AND po.deleted = FALSE WHERE p.id IN
#{targetId}
AND p.entry_type = 'NORMAL' AND p.deleted = FALSE ORDER BY p.id FOR UPDATE OF p



    p.deleted = FALSE
    AND p.event_at >= #{timeRange.startAt}
    AND p.event_at < #{timeRange.endAt}

        AND FALSE


            AND po.purchaser_id IN
            #{purchaserId}


    AND p.id = #{query.payableId}
    AND p.supplier_id = #{query.supplierId}

        AND p.supplier_name_snapshot ILIKE CONCAT('%', #{query.supplierName}, '%')


        AND po.order_no ILIKE CONCAT('%', #{query.purchaseOrderNo}, '%')


        AND p.entry_type = #{query.entryType}


        AND p.entry_type = 'NORMAL'
        AND CASE WHEN written.writtenOffAmount = 0 THEN 'OPEN'
                 WHEN GREATEST(p.amount - red.redAmount - written.writtenOffAmount, 0) = 0
                      AND GREATEST(written.writtenOffAmount - (p.amount - red.redAmount), 0) = 0 THEN 'SETTLED'
                 ELSE 'PARTIAL' END = #{query.settleState}


ORDER BY p.event_at DESC, p.id DESC
